/**
 * JavaScript counterparts of the motion tokens in app.css, for Svelte
 * transitions, the Web Animations API, and anything else that cannot read a
 * CSS custom property. Values must stay in sync with the theme.
 */

export type Easing = (t: number) => number;

/** Durations in milliseconds, matching the --duration-* tokens. */
export const duration = {
	instant: 100,
	fast: 160,
	base: 240,
	slow: 360,
	deliberate: 560,
	ambient: 2000
} as const;

/** Delay between siblings in a sequence, matching --stagger. */
export const stagger = 60;

/** A CSS cubic-bezier() as a function of progress, solved with Newton's method. */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number): Easing {
	const cx = 3 * x1;
	const bx = 3 * (x2 - x1) - cx;
	const ax = 1 - cx - bx;
	const cy = 3 * y1;
	const by = 3 * (y2 - y1) - cy;
	const ay = 1 - cy - by;

	const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
	const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
	const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;

	function solveX(x: number) {
		let t = x;
		for (let i = 0; i < 8; i++) {
			const error = sampleX(t) - x;
			if (Math.abs(error) < 1e-6) return t;
			const slope = slopeX(t);
			if (Math.abs(slope) < 1e-6) break;
			t -= error / slope;
		}
		// Newton can stall on flat segments; bisection always converges.
		let lower = 0;
		let upper = 1;
		t = x;
		while (upper - lower > 1e-6) {
			if (sampleX(t) < x) lower = t;
			else upper = t;
			t = (lower + upper) / 2;
		}
		return t;
	}

	return (t) => (t <= 0 ? 0 : t >= 1 ? 1 : sampleY(solveX(t)));
}

/** The house curve: a quick start that settles softly. Use for entrances. */
export const easeOut = cubicBezier(0.22, 1, 0.36, 1);
/** Accelerates away. Use for exits. */
export const easeIn = cubicBezier(0.55, 0, 1, 0.45);
/** Symmetric. Use to move between two resting states. */
export const easeInOut = cubicBezier(0.65, 0, 0.35, 1);

export type SpringOptions = {
	/** Period of the undamped oscillation in seconds. Lower is faster. */
	duration: number;
	/** Overshoot from 0 (none) to 1 (endless). */
	bounce: number;
};

/** Position of a unit spring released from 0 toward 1 after `t` seconds. */
export function springPosition({ duration, bounce }: SpringOptions, t: number) {
	const omega = (2 * Math.PI) / duration;
	const zeta = 1 - bounce;
	if (zeta >= 1) return 1 - Math.exp(-omega * t) * (1 + omega * t);

	const damped = omega * Math.sqrt(1 - zeta * zeta);
	return (
		1 -
		Math.exp(-zeta * omega * t) *
			(Math.cos(damped * t) + ((zeta * omega) / damped) * Math.sin(damped * t))
	);
}

/**
 * A spring as a duration and easing pair. The duration is the settling time,
 * so a transition that uses both ends exactly when the spring comes to rest.
 */
export function spring(options: SpringOptions): { duration: number; easing: Easing } {
	let settled = 0;
	for (let ms = 0; ms <= 4000; ms += 1) {
		if (Math.abs(1 - springPosition(options, ms / 1000)) > 0.002) settled = ms;
	}
	const total = Math.ceil(settled / 10) * 10;
	return {
		duration: total,
		easing: (t) => (t <= 0 ? 0 : t >= 1 ? 1 : springPosition(options, (t * total) / 1000))
	};
}

/**
 * The physical parameters behind the theme springs, for code that integrates
 * a spring itself, such as a drag release that must keep its velocity.
 */
export const springOptions = {
	smooth: { duration: 0.42, bounce: 0.12 },
	snappy: { duration: 0.3, bounce: 0 },
	bouncy: { duration: 0.5, bounce: 0.3 }
} as const satisfies Record<string, SpringOptions>;

/** The three springs in the theme: --ease-spring, -snappy, and -bouncy. */
export const springs = {
	/** Default for scale and position: a whisper of overshoot. */
	smooth: spring(springOptions.smooth),
	/** Critically damped and fast. For toggles, thumbs, and indicators. */
	snappy: spring(springOptions.snappy),
	/** Visible overshoot. For playful, celebratory, or tactile moments. */
	bouncy: spring(springOptions.bouncy)
};

/** Physics presets for Svelte's `Spring` class from `svelte/motion`. */
export const springPresets = {
	smooth: { stiffness: 0.15, damping: 0.8 },
	snappy: { stiffness: 0.25, damping: 0.9 },
	bouncy: { stiffness: 0.12, damping: 0.45 }
} as const;

import type { Attachment } from 'svelte/attachments';
import { springPresets } from './easing.js';
import { prefersReducedMotion } from './media.js';
import { SpringValue } from './spring-value.js';

/** What moved the selection: a pointer or the keyboard. */
export type EdgeCause = 'pointer' | 'key';

/**
 * Draws an indicator from two edges that travel on their own springs. On a
 * pointer move the edge facing the new item leaves first on a snappy spring
 * and the trailing edge follows on a softer one, so the indicator stretches
 * toward its target and then gathers itself, like an inchworm. Both springs
 * keep their velocity, so a second click mid-move bends the indicator toward
 * the new target instead of restarting it. Arrow keys fire in quick runs, so
 * when the host reports `key`, both edges move together on the snappy spring.
 *
 * The edges are written to the container as `--edge-left`, `--edge-right`,
 * `--edge-top`, and `--edge-height` in pixels, and every item receives its own
 * offset as `--edge-x`, so labels can clip a highlighted copy of themselves to
 * the indicator and recolor exactly as an edge crosses them. The container gets
 * `data-indicator` while the indicator is in place, so items can drop the
 * fallback they show before hydration. First placement, resizes, moves to
 * another row, and reduced motion jump without animating.
 *
 * ```svelte
 * <script>
 *   const thumb = edgeIndicator({ item: '[data-item]', active: '[data-state="on"]' });
 * </script>
 * <div onpointerdown={() => (thumb.cause = 'pointer')}>
 *   <span hidden {@attach thumb.attach}></span>
 * </div>
 * ```
 */
export function edgeIndicator({ item, active }: { item: string; active: string }) {
	const control = {
		/** Set by the host just before a selection changes, then consumed. */
		cause: null as EdgeCause | null,
		attach: ((indicator) => {
			const container = indicator.parentElement;
			if (!container) return;

			const write = () => {
				container.style.setProperty('--edge-left', `${left.current}px`);
				container.style.setProperty('--edge-right', `${right.current}px`);
			};
			const left = new SpringValue(0, { preset: springPresets.snappy, onUpdate: write });
			const right = new SpringValue(0, { preset: springPresets.snappy, onUpdate: write });
			let current: HTMLElement | null = null;
			let row = 0;

			// Offsets ignore transforms, so a pressed item's scale never leaks in.
			const offset = (el: HTMLElement) => {
				let x = 0;
				let y = 0;
				for (let node: HTMLElement | null = el; node && node !== container;) {
					x += node.offsetLeft;
					y += node.offsetTop;
					node = node.offsetParent as HTMLElement | null;
				}
				return { x, y };
			};

			const place = (resize: boolean) => {
				const cause = control.cause;
				control.cause = null;

				for (const el of container.querySelectorAll<HTMLElement>(item)) {
					el.style.setProperty('--edge-x', `${offset(el).x}px`);
				}

				const target = container.querySelector<HTMLElement>(`${item}${active}`);
				if (!target) {
					current = null;
					indicator.hidden = true;
					container.removeAttribute('data-indicator');
					return;
				}

				const { x, y } = offset(target);
				const nextLeft = x;
				const nextRight = x + target.offsetWidth;
				container.style.setProperty('--edge-top', `${y}px`);
				container.style.setProperty('--edge-height', `${target.offsetHeight}px`);

				// A move onto another row of a wrapped list jumps: sliding sideways
				// on the wrong row would point at the wrong item on the way.
				const instant =
					resize || current === null || current === target || y !== row || prefersReducedMotion();
				current = target;
				row = y;

				if (instant) {
					left.jump(nextLeft);
					right.jump(nextRight);
				} else {
					// Moving right, the right edge leads; moving left, the left one does.
					const rightward = nextLeft > left.current;
					const { snappy, smooth } = springPresets;
					left.set(nextLeft, { preset: cause === 'key' || !rightward ? snappy : smooth });
					right.set(nextRight, { preset: cause === 'key' || rightward ? snappy : smooth });
				}
				indicator.hidden = false;
				container.setAttribute('data-indicator', '');
			};

			const resizes =
				typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(() => place(true));
			// Only the container and the items: a sibling such as a hover pill
			// resizes as the pointer moves, and must not snap a glide in flight.
			const observeSizes = () => {
				if (!resizes) return;
				resizes.disconnect();
				resizes.observe(container);
				for (const el of container.querySelectorAll(item)) resizes.observe(el);
			};

			const mutations = new MutationObserver((records) => {
				if (records.some((record) => record.type === 'childList')) observeSizes();
				place(false);
			});
			mutations.observe(container, {
				subtree: true,
				childList: true,
				attributes: true,
				attributeFilter: ['data-state']
			});

			observeSizes();
			place(true);

			return () => {
				left.stop();
				right.stop();
				mutations.disconnect();
				resizes?.disconnect();
				container.removeAttribute('data-indicator');
			};
		}) as Attachment<HTMLElement>
	};
	return control;
}

export {
	cubicBezier,
	duration,
	easeIn,
	easeInOut,
	easeOut,
	spring,
	springOptions,
	springPosition,
	springPresets,
	springs,
	stagger,
	type Easing,
	type SpringOptions
} from './easing.js';
export { edgeIndicator, type EdgeCause } from './edge-indicator.js';
export { hasFinePointer, prefersReducedMotion } from './media.js';
export { magnetic, pointerPosition, type MagneticOptions } from './pointer.js';
export { reveal, type RevealEffect, type RevealOptions } from './reveal.js';
export { SpringValue, type SpringPreset, type SpringValueOptions } from './spring-value.js';
export { blurIn, pop, rise } from './transitions.js';

/** True when the reader asked the operating system to minimize motion. */
export function prefersReducedMotion(): boolean {
	return (
		typeof window !== 'undefined' &&
		typeof window.matchMedia === 'function' &&
		window.matchMedia('(prefers-reduced-motion: reduce)').matches
	);
}

/** True when the primary input can hover precisely, such as a mouse or trackpad. */
export function hasFinePointer(): boolean {
	return (
		typeof window !== 'undefined' &&
		typeof window.matchMedia === 'function' &&
		window.matchMedia('(hover: hover) and (pointer: fine)').matches
	);
}

import type { Attachment } from 'svelte/attachments';
import { springPresets } from './easing.js';
import { SpringValue, type SpringPreset } from './spring-value.js';
import { hasFinePointer, prefersReducedMotion } from './media.js';

/**
 * Track the pointer inside an element as CSS custom properties:
 * `--pointer-x` and `--pointer-y` in pixels from the top left, and
 * `--pointer-active` as 1 while hovered and 0 otherwise. Style anything from
 * those values, such as a radial glow that follows the cursor. Touch screens
 * and reduced motion keep `--pointer-active` at 0.
 *
 * ```svelte
 * <div {@attach pointerPosition()} class="bg-[radial-gradient(...at_var(--pointer-x)_var(--pointer-y)...)]">
 * ```
 */
export function pointerPosition(): Attachment<HTMLElement> {
	return (node) => {
		// Effects built on the position are decoration: skip them for touch and
		// for readers who asked for less motion.
		if (!hasFinePointer() || prefersReducedMotion()) {
			node.style.setProperty('--pointer-active', '0');
			return () => node.style.removeProperty('--pointer-active');
		}

		let frame = 0;
		let x = 0;
		let y = 0;

		const write = () => {
			frame = 0;
			node.style.setProperty('--pointer-x', `${x}px`);
			node.style.setProperty('--pointer-y', `${y}px`);
		};
		const move = (event: PointerEvent) => {
			const rect = node.getBoundingClientRect();
			x = Math.round(event.clientX - rect.left);
			y = Math.round(event.clientY - rect.top);
			node.style.setProperty('--pointer-active', '1');
			frame ||= requestAnimationFrame(write);
		};
		const leave = () => node.style.setProperty('--pointer-active', '0');

		node.style.setProperty('--pointer-active', '0');
		node.addEventListener('pointermove', move);
		node.addEventListener('pointerleave', leave);
		return () => {
			cancelAnimationFrame(frame);
			node.removeEventListener('pointermove', move);
			node.removeEventListener('pointerleave', leave);
			for (const name of ['--pointer-x', '--pointer-y', '--pointer-active']) {
				node.style.removeProperty(name);
			}
		};
	};
}

export type MagneticOptions = {
	/**
	 * Share of the pointer's offset from center that the element follows at
	 * full pull. The pull weakens with distance like a real magnet and fades to
	 * nothing at the edge of the field, so crossing it never jolts the element.
	 */
	strength?: number;
	/** Largest distance in pixels the element may travel. */
	limit?: number;
	/** How far past its edges, in pixels, the element starts to feel the pointer. */
	field?: number;
	/**
	 * Largest stretch toward the pointer, as a share of the element's length.
	 * The element thins across by half as much, which roughly keeps its area,
	 * and wobbles through a squash or two when the pointer lets go. `0` keeps
	 * it rigid.
	 */
	stretch?: number;
	/**
	 * Selector for an inner layer, such as the label, that keeps its shape while
	 * the body stretches and drifts further toward the pointer, so it reads as
	 * a layer above. The layer needs a box display, such as `inline-flex`.
	 */
	content?: string;
};

/** Stretch gained per pixel of pull: 1% per 1.2px. */
const STRETCH_PER_PX = 1 / 120;
/** Share of the body's travel the content layer adds on top, for parallax. */
const CONTENT_DEPTH = 0.5;
/**
 * Much looser than the follow (a damping ratio near 0.4), so when the pointer
 * lets go the body jiggles through a squash or two before it settles.
 */
const WOBBLE: SpringPreset = { stiffness: 0.18, damping: 0.33 };

/**
 * Let an element stretch toward a nearby pointer like something soft on a
 * magnet, then wobble home when the pointer moves away. The pull starts
 * `field` pixels past the element's edges. Mark a label inside with
 * `data-magnetic-content` to keep it undistorted and floating above the body.
 * Only fine pointers get the effect, and reduced motion disables it.
 *
 * ```svelte
 * <span {@attach magnetic()} class="inline-flex">
 *   <Button><span data-magnetic-content class="inline-flex items-center gap-2">Generate</span></Button>
 * </span>
 * ```
 */
export function magnetic({
	strength = 0.5,
	limit = 16,
	field = 96,
	stretch = 0.12,
	content = '[data-magnetic-content]'
}: MagneticOptions = {}): Attachment<HTMLElement> {
	return (node) => {
		if (!hasFinePointer() || prefersReducedMotion()) return;

		const layer = content ? node.querySelector<HTMLElement>(content) : null;
		let pointer: { x: number; y: number } | null = null;
		let frame = 0;
		// The pull's direction, held once the pull fades out: a spring settling
		// around zero has no direction of its own, and the wobble should stay on
		// the axis the body was stretched along.
		let heading = 0;

		// Individual `translate` plus a `transform` for the stretch, so utilities
		// such as `active:scale-*` on the element still compose.
		const render = () => {
			const dx = x.current;
			const dy = y.current;
			if (Math.hypot(dx, dy) > 1) heading = Math.atan2(dy, dx);
			const s = amount.current;
			// At rest the element gets its own styles back, so utilities such as
			// `-translate-x-1/2` apply again between visits.
			if (dx === 0 && dy === 0 && s === 0) {
				clear();
				return;
			}
			const turn = (scale: string) =>
				s === 0 ? '' : `rotate(${heading}rad) scale(${scale}) rotate(${-heading}rad)`;
			node.style.translate = `${dx.toFixed(2)}px ${dy.toFixed(2)}px`;
			node.style.transform = turn(`${1 + s}, ${1 - s / 2}`);
			if (layer) {
				layer.style.translate = `${(dx * CONTENT_DEPTH).toFixed(2)}px ${(dy * CONTENT_DEPTH).toFixed(2)}px`;
				// The exact inverse of the stretch, so the content never distorts.
				layer.style.transform = turn(`${1 / (1 + s)}, ${1 / (1 - s / 2)}`);
			}
		};
		const clear = () => {
			for (const element of [node, layer]) {
				element?.style.removeProperty('translate');
				element?.style.removeProperty('transform');
			}
		};
		// Stretch follows the travel, on its own looser spring.
		const follow = () => {
			render();
			amount.set(Math.min(Math.hypot(x.current, y.current) * STRETCH_PER_PX, stretch));
		};
		const x = new SpringValue(0, { preset: springPresets.snappy, onUpdate: follow });
		const y = new SpringValue(0, { preset: springPresets.snappy, onUpdate: follow });
		const amount = new SpringValue(0, { preset: WOBBLE, onUpdate: render, precision: 0.0005 });

		const pull = (px: number, py: number) => {
			if (px === x.target && py === y.target) return;
			x.set(px);
			y.set(py);
		};

		const aim = () => {
			frame = 0;
			if (!pointer) return;
			const rect = node.getBoundingClientRect();
			// Measured from where the element rests, so its own travel never feeds
			// back into the pull.
			const dx = pointer.x - (rect.left + rect.width / 2 - x.current);
			const dy = pointer.y - (rect.top + rect.height / 2 - y.current);
			const size = Math.max(node.offsetWidth || rect.width, node.offsetHeight || rect.height);
			const t = Math.min(Math.hypot(dx, dy) / (size / 2 + field), 1);
			const force = strength * (1 - t) ** 2;
			const length = Math.hypot(dx, dy) * force;
			const clamp = length > limit ? limit / length : 1;
			pull(dx * force * clamp, dy * force * clamp);
		};

		const move = (event: PointerEvent) => {
			if (event.pointerType === 'touch') return;
			pointer = { x: event.clientX, y: event.clientY };
			frame ||= requestAnimationFrame(aim);
		};
		const release = () => {
			pointer = null;
			pull(0, 0);
		};

		const root = node.ownerDocument.documentElement;
		const view = node.ownerDocument.defaultView ?? window;
		view.addEventListener('pointermove', move, { passive: true });
		view.addEventListener('blur', release);
		root.addEventListener('pointerleave', release);
		return () => {
			cancelAnimationFrame(frame);
			view.removeEventListener('pointermove', move);
			view.removeEventListener('blur', release);
			root.removeEventListener('pointerleave', release);
			for (const spring of [x, y, amount]) spring.stop();
			clear();
		};
	};
}

import type { Attachment } from 'svelte/attachments';
import { duration as durations, stagger as staggerStep } from './easing.js';
import { prefersReducedMotion } from './media.js';

export type RevealEffect = 'rise' | 'blur' | 'fade' | 'scale';

export type RevealOptions = {
	/** How the content arrives. */
	effect?: RevealEffect;
	/** Animate each child in sequence instead of the element as a whole. */
	children?: boolean;
	/** Milliseconds between children when `children` is set. */
	stagger?: number;
	/** Milliseconds before the first element starts. */
	delay?: number;
	/** Milliseconds for each element's entrance. */
	duration?: number;
	/** Fraction of the element that must be visible before it reveals. */
	threshold?: number;
	/** Grow or shrink the viewport used to detect visibility. */
	rootMargin?: string;
};

/** The Web Animations API cannot read custom properties, so mirror --ease-out. */
const EASE_OUT = 'cubic-bezier(0.22, 1, 0.36, 1)';

const keyframes: Record<RevealEffect, Keyframe[]> = {
	rise: [
		{ opacity: 0, translate: '0 0.75rem' },
		{ opacity: 1, translate: '0 0' }
	],
	blur: [
		{ opacity: 0, filter: 'blur(8px)', translate: '0 0.25rem' },
		{ opacity: 1, filter: 'blur(0)', translate: '0 0' }
	],
	fade: [{ opacity: 0 }, { opacity: 1 }],
	scale: [
		{ opacity: 0, scale: '0.96' },
		{ opacity: 1, scale: '1' }
	]
};

/**
 * Reveal content the first time it scrolls into view.
 *
 * ```svelte
 * <ul {@attach reveal({ children: true })}>...</ul>
 * ```
 *
 * Content is never hidden for readers who prefer reduced motion, in browsers
 * without IntersectionObserver, or before JavaScript runs.
 */
export function reveal(options: RevealOptions = {}): Attachment<HTMLElement> {
	const {
		effect = 'rise',
		children = false,
		stagger = staggerStep,
		delay = 0,
		duration = durations.deliberate,
		threshold = 0.15,
		rootMargin = '0px 0px -8% 0px'
	} = options;

	return (node) => {
		if (prefersReducedMotion() || typeof IntersectionObserver === 'undefined') return;

		const targets = children ? (Array.from(node.children) as HTMLElement[]) : [node];
		const animations: Animation[] = [];
		for (const target of targets) target.style.opacity = '0';

		const observer = new IntersectionObserver(
			(entries) => {
				if (!entries.some((entry) => entry.isIntersecting)) return;
				observer.disconnect();
				targets.forEach((target, index) => {
					target.style.removeProperty('opacity');
					if (typeof target.animate !== 'function') return;
					animations.push(
						target.animate(keyframes[effect], {
							duration,
							delay: delay + index * stagger,
							easing: EASE_OUT,
							fill: 'backwards'
						})
					);
				});
			},
			{ threshold, rootMargin }
		);
		observer.observe(node);

		return () => {
			observer.disconnect();
			for (const animation of animations) animation.cancel();
			for (const target of targets) target.style.removeProperty('opacity');
		};
	};
}

import { prefersReducedMotion } from './media.js';
import { springPresets } from './easing.js';

/** Physics for a `SpringValue`, in the same units as `springPresets`. */
export type SpringPreset = { stiffness: number; damping: number };

export type SpringValueOptions = {
	/** Physics preset. Defaults to `springPresets.smooth`. */
	preset?: SpringPreset;
	/** Called with the new value on every frame, and once on each jump. */
	onUpdate?: (value: number) => void;
	/** Called once each time the spring comes to rest. */
	onRest?: (value: number) => void;
	/** Distance and speed under which the spring snaps to rest. */
	precision?: number;
};

/**
 * A number that follows its target on a spring and keeps its velocity when the
 * target changes, stepped the way `svelte/motion` steps `Spring` so the
 * `springPresets` read the same. Unlike `Spring`, importing it touches no
 * browser API, so components that use it render in SSR and jsdom tests. The
 * animation frame loop sleeps at rest, and reduced motion jumps straight to
 * the target.
 */
export class SpringValue {
	#current: number;
	#last: number;
	#target: number;
	#preset: SpringPreset;
	#precision: number;
	#frame = 0;
	#then = 0;
	#onUpdate?: (value: number) => void;
	#onRest?: (value: number) => void;

	constructor(value: number, options: SpringValueOptions = {}) {
		this.#current = this.#last = this.#target = value;
		this.#preset = options.preset ?? springPresets.smooth;
		this.#precision = options.precision ?? 0.01;
		this.#onUpdate = options.onUpdate;
		this.#onRest = options.onRest;
	}

	/** The value on the current frame. */
	get current() {
		return this.#current;
	}

	/** Where the spring is heading. */
	get target() {
		return this.#target;
	}

	/** Units per 60fps frame, signed toward increasing values. */
	get velocity() {
		return this.#current - this.#last;
	}

	/** True while the spring is moving. */
	get moving() {
		return this.#frame !== 0;
	}

	/**
	 * Heads for `target`, keeping the current velocity. `velocity` adds a kick
	 * in units per frame, for flicks and pops. `instant` or reduced motion
	 * jumps instead.
	 */
	set(
		target: number,
		options: { preset?: SpringPreset; velocity?: number; instant?: boolean } = {}
	) {
		if (options.preset) this.#preset = options.preset;
		if (options.instant || typeof requestAnimationFrame === 'undefined' || prefersReducedMotion()) {
			this.jump(target);
			return;
		}
		this.#target = target;
		if (options.velocity) this.#last = this.#current - options.velocity;
		if (!this.#frame) {
			this.#then = performance.now();
			this.#frame = requestAnimationFrame(this.#tick);
		}
	}

	/** Moves straight to `value` and stops. */
	jump(value: number) {
		this.stop();
		this.#current = this.#last = this.#target = value;
		this.#onUpdate?.(value);
	}

	/** Stops where it is, dropping any velocity. */
	stop() {
		if (this.#frame) cancelAnimationFrame(this.#frame);
		this.#frame = 0;
		this.#last = this.#current;
	}

	/**
	 * Advances by `dt` frames at 60fps. Returns true once at rest. Exposed for
	 * tests and for hosts that drive several springs from one loop.
	 */
	step(dt: number) {
		const velocity = (this.#current - this.#last) / (dt || 1 / 60);
		const force = this.#preset.stiffness * (this.#target - this.#current);
		const damper = this.#preset.damping * velocity;
		const delta = (velocity + force - damper) * dt;
		this.#last = this.#current;
		if (
			Math.abs(delta) < this.#precision &&
			Math.abs(this.#target - this.#current) < this.#precision
		) {
			this.#current = this.#last = this.#target;
			return true;
		}
		this.#current += delta;
		return false;
	}

	#tick = (now: number) => {
		// Clamped so a blocked thread or a hidden tab cannot fling the value, and a
		// frame stamped before the loop started cannot step it backwards.
		const dt = (Math.min(Math.max(now - this.#then, 0), 1000 / 30) * 60) / 1000;
		this.#then = now;
		const settled = this.step(dt);
		this.#onUpdate?.(this.#current);
		if (settled) {
			this.#frame = 0;
			this.#onRest?.(this.#current);
		} else {
			this.#frame = requestAnimationFrame(this.#tick);
		}
	};
}

import type { TransitionConfig } from 'svelte/transition';
import { duration as durations, easeOut, springs, type Easing } from './easing.js';
import { prefersReducedMotion } from './media.js';

type BaseParams = {
	delay?: number;
	duration?: number;
	easing?: Easing;
};

/** Reduced motion keeps the change legible with a short opacity crossfade. */
function crossfade(delay: number): TransitionConfig {
	return { delay, duration: durations.fast, css: (t) => `opacity: ${t}` };
}

/** Rises into place while fading in. The default entrance for content. */
export function rise(
	_node: Element,
	{
		delay = 0,
		duration = durations.deliberate,
		easing = easeOut,
		y = 12
	}: BaseParams & {
		/** Starting offset in pixels. Negative values drop in from above. */
		y?: number;
	} = {}
): TransitionConfig {
	if (prefersReducedMotion()) return crossfade(delay);
	return {
		delay,
		duration,
		easing,
		css: (t, u) => `opacity: ${t}; translate: 0 ${u * y}px`
	};
}

/** Resolves from a soft blur. For headlines, generated text, and AI output. */
export function blurIn(
	_node: Element,
	{
		delay = 0,
		duration = durations.deliberate,
		easing = easeOut,
		blur = 8,
		y = 4
	}: BaseParams & {
		/** Starting blur radius in pixels. */
		blur?: number;
		/** Starting offset in pixels. */
		y?: number;
	} = {}
): TransitionConfig {
	if (prefersReducedMotion()) return crossfade(delay);
	return {
		delay,
		duration,
		easing,
		css: (t, u) => `opacity: ${t}; filter: blur(${u * blur}px); translate: 0 ${u * y}px`
	};
}

/**
 * Springs up from slightly smaller. For popovers, badges, and anything that
 * appears in response to a direct action. Opacity follows a plain curve so the
 * spring's overshoot never pushes it past fully opaque.
 */
export function pop(
	_node: Element,
	{
		delay = 0,
		scale = 0.94,
		spring = springs.smooth
	}: {
		delay?: number;
		/** Starting scale. */
		scale?: number;
		/** Any spring from `springs`, or your own from `spring()`. */
		spring?: { duration: number; easing: Easing };
	} = {}
): TransitionConfig {
	if (prefersReducedMotion()) return crossfade(delay);
	return {
		delay,
		duration: spring.duration,
		css: (t) => {
			const s = spring.easing(t);
			return `opacity: ${Math.min(1, easeOut(t) * 1.6)}; scale: ${scale + (1 - scale) * s}`;
		}
	};
}
